// Monta o contexto unico do fluxo, juntando o webhook (mensagem) com o
// GET /conversations/:id (contato, labels, atributos, assignee, status).
// O anti-loop ja foi feito no CRM (a Automacao so entrega msg de cliente),
// entao aqui NAO precisamos filtrar senderType.

const cfg = $('Config').first().json;
const conv = ($input.first().json && $input.first().json.data) || {};
const contato = conv.contact || {};
const attrs = conv.customAttributes || {};

// Telefone e a identidade real do lead no WhatsApp. E a chave da sessao
// (Redis + memoria do chat). NUNCA usar o externalId da mensagem — aquilo
// e o id da msg no WhatsApp (3EB0...), nao o telefone.
const telefone = String(contato.telefone || '').replace(/\D/g, '');
const id_phone = telefone ? telefone + '@s.whatsapp.net' : '';

const labels = Array.isArray(conv.labels)
  ? conv.labels.map(l => (typeof l === 'string' ? l : (l.name || l.label || ''))).filter(Boolean)
  : [];

// Guardas: quando o fluxo NAO deve responder.
const humanoAtivo =
  attrs.human_active === true ||
  attrs.handoff_to_human === true ||
  (conv.assigneeId !== null && conv.assigneeId !== undefined);

const encerrada =
  conv.status === 'resolved' ||
  ['fechado', 'perdido', 'desinteressado', 'convertido'].some(l => labels.includes(l));

const deveProcessar = !humanoAtivo && !encerrada && !!id_phone;

return [{
  json: {
    ...cfg,
    id_phone,
    telefone,
    nome: contato.nome || '',
    labels,
    status: conv.status || null,
    assignee_id: conv.assigneeId || null,
    custom_attributes: attrs,
    deve_processar: deveProcessar,
    motivo_skip: humanoAtivo ? 'humano atendendo' : (encerrada ? 'conversa encerrada' : (!id_phone ? 'sem telefone' : '')),
  }
}];

// Reanexa o contexto (o node de audio devolve so { text }) e usa a
// transcricao como mensagem.
const ctx = $('Contexto').first().json;
const texto = $input.first().json.text || '';
return [{ json: { ...ctx, msg: texto } }];

// Debounce: se durante a espera chegou OUTRA mensagem, esta execucao para
// (a ultima execucao e quem responde). Se esta e a ultima, junta a rajada
// inteira num texto so e limpa a fila.
const ctx = $('Contexto').first().json;
const minhaMsg = $('Mensagem').first().json.msg || '';

const raw = $input.first().json;
let fila = raw.propertyName || raw.value || raw.data || [];
if (typeof fila === 'string') { try { fila = JSON.parse(fila); } catch { fila = [fila]; } }
if (!Array.isArray(fila)) fila = [];

const ultima = fila.length ? String(fila[fila.length - 1]) : '';
const souAUltima = ultima === String(minhaMsg);

if (!souAUltima) {
  return [{ json: { ...ctx, sou_a_ultima: false, msg: '' } }];
}

// Junta a rajada em texto natural: "Oi. Tudo bem? Queria saber o preco."
const agrupada = fila
  .map(s => String(s).trim())
  .filter(Boolean)
  .map(s => (/[.!?]$/.test(s) ? s : s + '.'))
  .join(' ');

return [{ json: { ...ctx, sou_a_ultima: true, msg: agrupada } }];

