// Normaliza a saida da IA e reanexa o contexto (conversation_id, auth, urls).
const ctx = $('Contexto').first().json;
const o = ($input.first().json.output) || $input.first().json || {};

const limpa = (t) => String(t || '')
  .replace(/[\u0000-\u001f]/g, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

const transferir = o.transferir_para_humano === true || o.transferir_para_humano === 'true';
const resolver = transferir ? false : (o.resolver_conversa === true || o.resolver_conversa === 'true');

const ETAPAS = ['novo-lead','em-atendimento','aguardando-resposta','agendado','convertido','perdido'];
let etapa = limpa(o.etapa_final || 'em-atendimento');
if (!ETAPAS.includes(etapa)) etapa = 'em-atendimento';

return [{
  json: {
    ...ctx,
    resposta: limpa(o.mensagem_de_resposta),
    etapa,
    transferir_para_humano: transferir,
    resolver_conversa: resolver,
  }
}];

// Sorteia um agente online. Se nao houver nenhum, apenas marca handoff
// (a conversa fica sem assignee e o time ve na fila de nao-atribuidas).
const ctx = $('Normaliza').first().json;
const raw = $input.first().json;
const lista = Array.isArray(raw.data) ? raw.data : (Array.isArray(raw) ? raw : []);

if (!lista.length) {
  return [{ json: { ...ctx, tem_agente: false, agente_id: null } }];
}
const escolhido = lista[Math.floor(Math.random() * lista.length)];
return [{ json: { ...ctx, tem_agente: true, agente_id: escolhido.id, agente_nome: escolhido.nome || escolhido.email } }];
